    47→	function performSearch() {
    48→		// Clear previous highlights
    49→		document.querySelectorAll('.search-highlight-overlay').forEach((el) => el.remove());
    50→		highlightElements = [];
    51→		matchCount = 0;
    52→		currentMatchIndex = 0;
    53→
    54→		if (!searchQuery.trim() || pagesData.length === 0) return;
    55→
    56→		const query = matchCase ? searchQuery : searchQuery.toLowerCase();
    57→
    58→		// Search through each page's text data
    59→		pagesData.forEach((pageData) => {
    60→			// Build combined text with character position mapping
    61→			interface CharInfo {
    62→				itemIndex: number;
    63→				charIndex: number;
    64→			}
    65→			const charMap: CharInfo[] = [];
    66→			let combinedText = '';
    67→
    68→			pageData.textItems.forEach((item, itemIndex) => {
    69→				for (let i = 0; i < item.str.length; i++) {
    70→					charMap.push({ itemIndex, charIndex: i });
    71→				}
    72→				combinedText += item.str;
    73→			});
    74→
    75→			// Find matches
    76→			const textToSearch = matchCase ? combinedText : combinedText.toLowerCase();
    77→			let searchPos = 0;
    78→
    79→			while (true) {
    80→				const matchIndex = textToSearch.indexOf(query, searchPos);
    81→				if (matchIndex === -1) break;
    82→
    83→				// Check whole word boundary if enabled
    84→				if (matchWholeWord) {
    85→					const charBefore = matchIndex > 0 ? textToSearch[matchIndex - 1] : ' ';
    86→					const charAfter =
    87→						matchIndex + query.length < textToSearch.length
    88→							? textToSearch[matchIndex + query.length]
    89→							: ' ';
    90→					const isWordBoundaryBefore = !/\w/.test(charBefore);
    91→					const isWordBoundaryAfter = !/\w/.test(charAfter);
    92→
    93→					if (!isWordBoundaryBefore || !isWordBoundaryAfter) {
    94→						searchPos = matchIndex + 1;
    95→						continue;
    96→					}
    97→				}
    98→
    99→				const matchEnd = matchIndex + query.length;
   100→				matchCount++;
   101→
   102→				// Find which text items this match spans
   103→				const startChar = charMap[matchIndex];
   104→				const endChar = charMap[matchEnd - 1];
   105→
   106→				if (!startChar || !endChar) {
   107→					searchPos = matchIndex + 1;
   108→					continue;
   109→				}
   110→
   111→				// Create highlights for each text item in this match
   112→				for (let itemIdx = startChar.itemIndex; itemIdx <= endChar.itemIndex; itemIdx++) {
   113→					const item = pageData.textItems[itemIdx];
   114→					const transform = item.transform;
   115→
   116→					// Transform matrix: [scaleX, skewY, skewX, scaleY, translateX, translateY]
   117→					const x = transform[4];
   118→					const y = transform[5];
   119→					const fontHeight = Math.abs(transform[3]); // scaleY = font height in PDF units
   120→
   121→					// Calculate the portion of this item that's highlighted
   122→					let highlightStartChar = 0;
   123→					let highlightEndChar = item.str.length;
   124→
   125→					if (itemIdx === startChar.itemIndex) {
   126→						highlightStartChar = startChar.charIndex;
   127→					}
   128→					if (itemIdx === endChar.itemIndex) {
   129→						highlightEndChar = endChar.charIndex + 1;
   130→					}
   131→
   132→					// item.width is already the total width in PDF units
   133→					const charWidth = item.width / item.str.length;
   134→					const highlightX = x + highlightStartChar * charWidth;
   135→					const highlightWidth = (highlightEndChar - highlightStartChar) * charWidth;
   136→
   137→					// Create highlight overlay
   138→					const highlight = document.createElement('div');
   139→					highlight.className = 'search-highlight-overlay';
   140→					highlight.dataset.matchIndex = String(matchCount - 1);
   141→
   142→					// Position in PDF coordinates, then scale to viewport
   143→					const scale = pageData.viewport.scale;
   144→					highlight.style.left = `${highlightX * scale}px`;
   145→					highlight.style.bottom = `${y * scale}px`;
   146→					highlight.style.width = `${Math.max(highlightWidth * scale, 4)}px`;
   147→					highlight.style.height = `${fontHeight * scale}px`;
   148→
   149→					pageData.pageWrapper.appendChild(highlight);
   150→					highlightElements.push(highlight);
   151→				}
   152→
   153→				searchPos = matchIndex + 1;
   154→			}
   155→		});
   156→
   157→		if (highlightElements.length > 0) {
   158→			scrollToMatch(0);
   159→		}
   160→	}
   161→
   162→	function scrollToMatch(index: number) {
   163→		// Remove current highlight styling
   164→		highlightElements.forEach((el) => el.classList.remove('current-match'));
   165→
   166→		if (matchCount === 0) return;
   167→
   168→		currentMatchIndex = ((index % matchCount) + matchCount) % matchCount;
   169→
   170→		// Find all highlights for this match and mark them as current
   171→		const currentHighlights = highlightElements.filter(
   172→			(el) => el.dataset.matchIndex === String(currentMatchIndex)
   173→		);
   174→
   175→		currentHighlights.forEach((el) => el.classList.add('current-match'));
   176→
   177→		if (currentHighlights.length > 0) {
   178→			currentHighlights[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
   179→		}
   180→	}
   181→
   182→	function nextMatch() {
   183→		scrollToMatch(currentMatchIndex + 1);
   184→	}
   185→
   186→	function prevMatch() {
   187→		scrollToMatch(currentMatchIndex - 1);
   188→	}
