   237→					nextMatch();
   238→				}
   239→			}
   240→			// Cmd+Shift+g: Previous match
   241→			if ((e.metaKey || e.ctrlKey) && e.key === 'g' && e.shiftKey && !e.altKey) {
   242→				if (hasPdf && matchCount > 0) {
   243→					e.preventDefault();
   244→					prevMatch();
   245→				}
   246→			}
   247→			// Cmd+Opt+c: Toggle match case
   248→			if ((e.metaKey || e.ctrlKey) && e.altKey && e.code === 'KeyC') {
   249→				if (hasPdf) {
