   253→			}
   254→			// Cmd+Opt+w: Toggle match whole word
   255→			if ((e.metaKey || e.ctrlKey) && e.altKey && e.code === 'KeyW') {
   256→				if (hasPdf) {
   257→					e.preventDefault();
   258→					toggleMatchWholeWord();
   259→				}
   260→			}
   261→		}
   262→		document.addEventListener('keydown', onKeydown, true);
   263→		return () => document.removeEventListener('keydown', onKeydown, true);
   264→	});
