   266→	async function handleFileChange(event: Event) {
   267→		if (!(event.target instanceof HTMLInputElement)) return;
   268→		const pdfjs = await loadPdfJs();
   269→		const input = event.target;
   270→
   271→		const container = document.getElementById('pdf-container');
   272→
   273→		if (input.files && input.files[0] && container) {
   274→			pdfFile = input.files[0];
   275→			pdfUrl = URL.createObjectURL(pdfFile);
   276→			container.innerHTML = '';
   277→			pagesData = [];
   278→			searchQuery = '';
   279→			matchCount = 0;
   280→
   281→			const fileReader = new FileReader();
   282→
   283→			fileReader.onload = async (e) => {
   284→				if (!e.target || !(e.target.result instanceof ArrayBuffer)) return;
   285→				const pdf = await pdfjs.getDocument({ data: new Uint8Array(e.target.result) }).promise;
   286→
   287→				for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
   288→					const page = await pdf.getPage(pageNum);
   289→					const viewport = page.getViewport({ scale: 1.5 });
   290→
   291→					// Create page wrapper
   292→					const pageWrapper = document.createElement('div');
   293→					pageWrapper.className = 'page-wrapper';
   294→					pageWrapper.style.width = `${viewport.width}px`;
   295→					pageWrapper.style.height = `${viewport.height}px`;
   296→
   297→					// Create and render canvas
   298→					const canvas = document.createElement('canvas');
   299→					const context = canvas.getContext('2d');
   300→
   301→					if (!context) return;
   302→
   303→					canvas.height = viewport.height;
   304→					canvas.width = viewport.width;
   305→
   306→					await page.render({ canvasContext: context, viewport }).promise;
   307→					pageWrapper.appendChild(canvas);
   308→
   309→					// Create and render text layer
   310→					const textLayerDiv = document.createElement('div');
   311→					textLayerDiv.className = 'textLayer';
   312→					const PDF_TO_CSS_UNITS = 96 / 72;
   313→					textLayerDiv.style.setProperty(
   314→						'--scale-factor',
   315→						(viewport.scale * PDF_TO_CSS_UNITS).toString()
   316→					);
   317→
   318→					const textContent = await page.getTextContent();
   319→
   320→					// Store text data for search
   321→					const textItems = textContent.items
   322→						.filter((item): item is TextItem => 'str' in item && item.str.length > 0)
   323→						.map((item) => ({
   324→							str: item.str,
   325→							transform: item.transform,
   326→							width: item.width,
   327→							height: item.height
   328→						}));
   329→
   330→					pagesData.push({
   331→						pageWrapper,
   332→						viewport: { width: viewport.width, height: viewport.height, scale: viewport.scale },
   333→						textItems
   334→					});
   335→
   336→					const textLayer = new pdfjs.TextLayer({
   337→						textContentSource: textContent,
   338→						container: textLayerDiv,
   339→						viewport: viewport
   340→					});
   341→					await textLayer.render();
   342→					pageWrapper.appendChild(textLayerDiv);
   343→
   344→					container.appendChild(pageWrapper);
   345→				}
   346→			};
   347→			fileReader.readAsArrayBuffer(pdfFile);
   348→		}
   349→	}
