//   this.#transform = [1, 0, 0, -1, -pageX, pageY + pageHeight]  (flips Y axis)
//   geom.transform  = [scaleX, skewY, skewX, scaleY, translateX, translateY]
//   tx is the result: a 6-element affine matrix in canvas/CSS coordinates

let angle = Math.atan2(tx[1], tx[0]);  // rotation angle from the matrix
```

---

### Step 2 — Compute `left` and `top`

```js
const fontHeight = Math.hypot(tx[2], tx[3]);   // actual rendered font height in PDF units
const fontAscent = fontHeight * TextLayer.#getAscent(fontFamily, style, lang); // ascent ratio * height

if (angle === 0) {
  left = tx[4];                      // translateX from the composed matrix
  top  = tx[5] - fontAscent;         // translateY minus ascent (align baseline → top-left)
} else {
  left = tx[4] + fontAscent * Math.sin(angle);
  top  = tx[5] - fontAscent * Math.cos(angle);
}
```

Then set on the DOM element:

```js
// In root container: expressed as percentages of page dimensions
