const wrapperRect = pageWrapper.getBoundingClientRect();

// Create overlay divs for each text div segment of this match.
// Using Range.getBoundingClientRect() gives pixel-perfect positions that
// account for CSS transforms (including scaleX) and actual font kerning,
// without modifying the text node content (no kerning disruption).
for (let divIdx = startPos.divIdx; divIdx <= endPos.divIdx; divIdx++) {
	const div = textDivs[divIdx];
	const textNode = div.firstChild;
	if (!textNode || textNode.nodeType !== Node.TEXT_NODE) continue;

	const segStart = divIdx === startPos.divIdx ? startPos.offset : 0;
	const segEnd =
		divIdx === endPos.divIdx
			? endPos.offset + 1
			: textContentItemsStr[divIdx].length;

	try {
		const range = document.createRange();
		range.setStart(textNode, segStart);
		range.setEnd(textNode, segEnd);
		const rect = range.getBoundingClientRect();

		if (rect.width === 0 && rect.height === 0) continue;

		const highlight = document.createElement('div');
		highlight.className = 'search-highlight-overlay';
		highlight.dataset.matchIndex = String(currentMatchIdx);
		highlight.style.left = `${rect.left - wrapperRect.left}px`;
		highlight.style.top = `${rect.top - wrapperRect.top}px`;
		highlight.style.width = `${rect.width}px`;
		highlight.style.height = `${rect.height}px`;
		pageWrapper.appendChild(highlight);
		highlightElements.push(highlight);
	} catch {
		// skip if range is invalid (e.g. offset out of bounds)
	}
}

